+
+            foreach (iterator_to_array($paragraph->childNodes) as $child) {
+                if ($child instanceof DOMElement && $child->localName !== 'pPr') {
+                    $paragraph->removeChild($child);
+                }
+            }
+
+            $run = $prototypeRun instanceof DOMElement
+                ? $prototypeRun->cloneNode(true)
+                : $this->document->createElementNS(self::WORD_NS, 'w:r');
+            foreach (iterator_to_array($run->childNodes) as $child) {
+                if ($child instanceof DOMElement && $child->localName !== 'rPr') {
+                    $run->removeChild($child);
+                }
+            }
+
+            $this->applyControlledFontSize($run, $value);
+            $text = $this->document->createElementNS(self::WORD_NS, 'w:t');
+            $text->setAttribute('xml:space', 'preserve');
