+                $put(6, $row, 2, $description);
+                $put(6, $row, 3, $result?->indicador ?: $result?->medio_verificacion);
+            } else {
+                $put(6, $row, 1, $description);
+                $put(6, $row, 2, $result?->indicador ?: $result?->medio_verificacion);
+            }
+        }
